{
  "missing_information": [
    {
      "category": "Trigger & Initiation",
      "gap": "It is unclear what event or condition initiates the verification test — whether it is scheduled, triggered by a code/design change, requested manually, or linked to a milestone.",
      "why_it_matters": "The trigger determines whether the start of the process can be automated and how it integrates with upstream workflows."
    },
    {
      "category": "Test Preparation Steps",
      "gap": "The specific activities involved in 'preparing' a verification test are not described — for example, configuring parameters, selecting test cases, setting up environments, or loading data.",
      "why_it_matters": "Preparation steps vary widely in automation potential; some may be fully scriptable while others require human judgment."
    },
    {
      "category": "Result Evaluation Criteria",
      "gap": "There is no definition of what constitutes a passing or failing result, or who or what system makes that determination.",
      "why_it_matters": "Without clear pass/fail criteria, it is impossible to automate the decision point that routes the process toward reporting or investigation."
    },
    {
      "category": "Investigation Subprocess",
      "gap": "The investigation step when 'something looks wrong' is not elaborated — its scope, duration, tools used, and possible outcomes are unknown.",
      "why_it_matters": "The investigation branch may loop back, escalate, or terminate the process; its structure is essential for accurate process modeling."
    },
    {
      "category": "Stakeholder Notification",
      "gap": "The identity of 'related people' who receive the shared result is not specified, nor is the channel or format used to share findings.",
      "why_it_matters": "Knowing the recipients and communication method determines whether notification can be automated and what data must be included."
    },
    {
      "category": "Report Content & Storage",
      "gap": "The structure, required content, and destination of the short report are not defined — it is unclear whether it follows a template or where it is stored.",
      "why_it_matters": "Standardized report content and storage location are prerequisites for automating report generation and archiving."
    }
  ],
  "clarification_questions": [
    {
      "id": "Q1",
      "question": "What event or condition triggers the start of a verification test — for example, is it a scheduled time, a change in a design artifact, a manual request, or a project milestone?",
      "targets": ["Trigger & Initiation"]
    },
    {
      "id": "Q2",
      "question": "What specific activities does the engineer perform when preparing a verification test, and are any of those activities currently supported by tools or scripts?",
      "targets": ["Test Preparation Steps"]
    },
    {
      "id": "Q3",
      "question": "How does the engineer determine that a result 'looks wrong' — are there defined numeric thresholds, comparison baselines, or formal acceptance criteria that guide this judgment?",
      "targets": ["Result Evaluation Criteria"]
    },
    {
      "id": "Q4",
      "question": "What does the investigation step involve, and what are the possible outcomes — for instance, can it result in re-running the test, escalating to another team, or closing the issue as a known limitation?",
      "targets": ["Investigation Subprocess"]
    },
    {
      "id": "Q5",
      "question": "Who are the 'related people' who receive the shared result after an investigation, and through what channel are they notified — for example, email, a shared system, or a meeting?",
      "targets": ["Stakeholder Notification"]
    },
    {
      "id": "Q6",
      "question": "Does the short report follow a fixed template or structure, and where is it stored or submitted once it is written?",
      "targets": ["Report Content & Storage"]
    }
  ]
}
